import { test, expect } from '@playwright/test';

test.describe('Async PDF Generation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/pdf-generator');
  });

  test('should initiate PDF generation and display loading message', async ({ page }) => {
    await page.getByRole('button', { name: /generate pdf/i }).click();
    const loadingMessage = page.getByText(/your pdf is being generated/i);
    await expect(loadingMessage).toBeVisible();
  });

  test('should download PDF when generation is complete', async ({ page }) => {
    await page.getByRole('button', { name: /generate pdf/i }).click();
    const downloadPromise = page.waitForEvent('download');
    await page.getByText(/your pdf is being generated/i);
    const download = await downloadPromise;
    const path = await download.path();
    expect(path).toBeTruthy();
    expect(path.endsWith('.pdf')).toBe(true);
  });
});
